<script lang="ts">
  import { translate, type Language } from './i18n';
  import { brushFromBounds, clampBrush, rangeFromBrush, recordsInBrush, type TimelineData } from './timeline';
  let {data=null,from='',to='',language='en',onrange=(_:string,__:string)=>{}}:{data:TimelineData|null;from:string;to:string;language?:Language;onrange?:(fromISO:string,toISO:string)=>void}=$props();
  const t=(s:string)=>translate(s,language);
  const uid=$props.id();
  let start=$state(0),end=$state(0),editing=$state(false);
  let dragAnchor:number|null=null;
  let capturedData=$state<TimelineData|null>(null);
  let context=$derived(editing&&capturedData?capturedData:data);
  let bins=$derived(context?.bins??[]);
  let selected=$derived(context?brushFromBounds(context,from,to):{start:0,end:0,clamped:false,outside:false});
  let range=$derived(context&&bins.length?rangeFromBrush(context,start,end):null);
  let selectedCount=$derived(context?recordsInBrush(context,start,end):0);
  let maximum=$derived(Math.max(0,...bins.map(bin=>bin.count)));
  $effect(()=>{if(!editing){start=selected.start;end=selected.end;}});
  function display(iso:string){return iso.slice(0,16).replace('T',' ');}
  function beginEditing(){if(!editing)capturedData=data;editing=true;}
  function commit(){if(context&&bins.length){const chosen=rangeFromBrush(context,start,end);onrange(chosen.from,chosen.to);}editing=false;}
  function changeStart(event:Event){beginEditing();const value=Number((event.currentTarget as HTMLInputElement).value);const brush=clampBrush(Math.min(value,end-1),end,bins.length);start=brush.start;end=brush.end;(event.currentTarget as HTMLInputElement).value=String(brush.start);}
  function changeEnd(event:Event){beginEditing();const value=Number((event.currentTarget as HTMLInputElement).value);const brush=clampBrush(start,Math.max(value,start+1),bins.length);start=brush.start;end=brush.end;(event.currentTarget as HTMLInputElement).value=String(brush.end);}
  function pointerBin(event:PointerEvent){const rect=(event.currentTarget as SVGSVGElement).getBoundingClientRect();return Math.min(bins.length-1,Math.max(0,Math.floor((event.clientX-rect.left)/rect.width*bins.length)));}
  function beginBrush(event:PointerEvent){if(event.button!==0||!bins.length)return;event.preventDefault();beginEditing();dragAnchor=pointerBin(event);start=dragAnchor;end=start+1;(event.currentTarget as SVGSVGElement).setPointerCapture(event.pointerId);}
  function moveBrush(event:PointerEvent){if(dragAnchor===null)return;const index=pointerBin(event);start=Math.min(dragAnchor,index);end=Math.max(dragAnchor,index)+1;}
  function endBrush(event:PointerEvent){if(dragAnchor===null)return;moveBrush(event);dragAnchor=null;commit();}
  function cancelBrush(){dragAnchor=null;editing=false;}
</script>
<section class="time-brush" aria-label={t('Visual time filter')}>
  {#if context&&bins.length}
    <div class="timeline-heading"><span class="timeline-title">{t('Time window')}</span><output class="selection-readout">{range?display(range.from):'—'} <span aria-hidden="true">→</span> {range?display(range.to):'—'} <small>UTC</small></output><span class="bin-count">{selectedCount.toLocaleString(language)} {t('records in highlighted bins')}</span></div>
    <svg class="histogram" viewBox="0 0 1000 68" preserveAspectRatio="none" role="img" aria-label={`${t('Retained records by occurrence time')}: ${context.total.toLocaleString(language)} ${t('records in context')}; ${t('Maximum bin')}: ${maximum}`} aria-describedby={`${uid}-description`} onpointerdown={beginBrush} onpointermove={moveBrush} onpointerup={endBrush} onpointercancel={cancelBrush}>
      <rect x="0" y="0" width="1000" height="68" fill="#eef0e7" rx="3"/>
      <rect x={start/bins.length*1000} y="0" width={(end-start)/bins.length*1000} height="68" fill="#dce7d7"/>
      {#each bins as bin,i}<rect x={i/bins.length*1000+1} y={64-bin.count/Math.max(1,maximum)*56} width={Math.max(1,1000/bins.length-2)} height={bin.count/Math.max(1,maximum)*56} fill={i>=start&&i<end?'#4b745d':'#adbda7'}><title>{display(bin.from)} → {display(bin.to)} UTC · {bin.count} {t('records')}</title></rect>{/each}
      <line x1={start/bins.length*1000+1} x2={start/bins.length*1000+1} y1="0" y2="68" stroke="#153f39" stroke-width="2" vector-effect="non-scaling-stroke"/>
      <line x1={end/bins.length*1000-1} x2={end/bins.length*1000-1} y1="0" y2="68" stroke="#153f39" stroke-width="2" vector-effect="non-scaling-stroke"/>
    </svg>
    <div class="brush-sliders"><div class="brush-labels"><label for={`${uid}-start`}>{t('Start')} <small>{range?display(range.from):'—'} UTC</small></label><label for={`${uid}-end`}>{t('End')} <small>{range?display(range.to):'—'} UTC</small></label></div><div class="brush-controls"><div class="brush-rail" style:background={`linear-gradient(to right, #d7dfd1 0%, #d7dfd1 ${start/bins.length*100}%, #4b745d ${start/bins.length*100}%, #4b745d ${end/bins.length*100}%, #d7dfd1 ${end/bins.length*100}%, #d7dfd1 100%)`}></div><input id={`${uid}-start`} class="start-handle" type="range" min="0" max={bins.length} step="1" value={start} aria-label={t('Start')} aria-valuetext={range?range.from:''} oninput={changeStart} onchange={commit} onblur={()=>{if(editing&&dragAnchor===null)commit();}}/><input id={`${uid}-end`} class="end-handle" type="range" min="0" max={bins.length} step="1" value={end} aria-label={t('End')} aria-valuetext={range?range.to:''} oninput={changeEnd} onchange={commit} onblur={()=>{if(editing&&dragAnchor===null)commit();}}/></div></div>
    <div class="timeline-footnote" id={`${uid}-description`}><span>{t('Drag the bars to select a range, or use the Start and End sliders. Applies when released.')} {t('Counts are retained records, not journeys or people.')}</span><span class="context-bounds">{display(context.from)} → {display(context.to)} UTC</span></div>
    {#if selected.clamped&&!editing}<p class="context-notice" role="status">{t(selected.outside?'The selected dates are outside this context. The graph keeps its existing range until you choose a new one.':'The existing range extends beyond this context. The handles show its visible portion; choosing a new range replaces it.')}</p>{/if}
    {#if context.truncated}<p class="context-notice">{t('Partial timeline: the retained-record query reached its work limit. Narrow the context or filters.')}</p>{/if}
    <details class="timeline-data"><summary>{t('Timeline data table')} · {context.total.toLocaleString(language)} {t('records in context')}</summary><div class="table-wrap"><table><caption>{t('Retained records by occurrence time')} · UTC{context.truncated?' · '+t('Partial'):''}</caption><thead><tr><th>{t('Start')}</th><th>{t('End')}</th><th>{t('Records')}</th></tr></thead><tbody>{#each bins as bin}<tr><td>{display(bin.from)}</td><td>{display(bin.to)}</td><td>{bin.count}</td></tr>{/each}</tbody></table></div></details>
  {:else}<p class="timeline-loading">{t(context?'No retained records timeline is available in this context.':'Loading time context…')}</p>{/if}
</section>
<style>
.time-brush{color:var(--ink,#253b36);font-size:11px;min-width:0}.timeline-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:9px}.timeline-title{font-weight:650}.selection-readout{font-variant-numeric:tabular-nums;color:#42594b;font-size:11px}.selection-readout small{font-size:9px}.bin-count{margin-left:auto;color:var(--muted,#626e66);font-size:10px}.histogram{display:block;width:100%;height:64px;cursor:crosshair;touch-action:none;user-select:none}.timeline-footnote{display:flex;gap:5px 16px;justify-content:space-between;color:var(--muted,#626e66);font-size:9px;line-height:1.6}.context-bounds{white-space:nowrap;font-variant-numeric:tabular-nums}.context-notice{font-size:10px;margin:6px 0 0;color:#78643e}.timeline-data{margin-top:4px}.timeline-data summary{min-height:30px;font-size:10px;font-weight:500;color:var(--muted,#626e66)}.timeline-data .table-wrap{max-height:240px}.timeline-data table{font-variant-numeric:tabular-nums;min-width:0;font-size:10px}.timeline-loading{margin:0;padding:12px 0;color:var(--muted,#626e66)}@media(max-width:650px){.timeline-heading{gap:3px 10px}.bin-count{margin-left:0;width:100%}.timeline-footnote{flex-direction:column}.context-bounds{font-size:8px}.selection-readout{font-size:10px}.histogram{height:54px}}

.brush-sliders{display:block;margin-top:8px}.brush-labels{display:flex;justify-content:space-between;gap:20px}.brush-labels label{display:flex;flex-direction:row;align-items:center;gap:8px;font-size:10px}.brush-labels small{font-size:9px;color:var(--muted,#626e66);font-weight:400}.brush-controls{position:relative;height:44px}.brush-rail{position:absolute;left:14px;right:14px;height:4px;top:20px;border-radius:4px;pointer-events:none}.brush-controls input{position:absolute;inset:0;appearance:none;-webkit-appearance:none;width:100%;height:44px;min-height:44px;margin:0;padding:0;border:0;background:transparent;pointer-events:none;touch-action:none;box-shadow:none}.brush-controls input::-webkit-slider-runnable-track{height:4px;background:transparent;border:0}.brush-controls input::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;pointer-events:auto;width:28px;height:28px;min-width:28px;min-height:28px;margin-top:-12px;border:2px solid #fffefa;border-radius:50%;background:#38674e;box-shadow:0 0 0 1px #38674e;cursor:ew-resize}.brush-controls input::-moz-range-track{height:4px;background:transparent;border:0}.brush-controls input::-moz-range-progress{background:transparent}.brush-controls input::-moz-range-thumb{pointer-events:auto;width:26px;height:26px;border:2px solid #fffefa;border-radius:50%;background:#38674e;box-shadow:0 0 0 1px #38674e;cursor:ew-resize}.brush-controls input:focus-visible{outline:2px solid var(--focus,#bd782a);outline-offset:0;border-radius:5px}@media(max-width:650px){.brush-labels label{flex-direction:column;align-items:flex-start;gap:0}.brush-labels label:last-child{align-items:flex-end}.brush-labels small{font-size:8px}}
</style>
